Program clone_Program(Program p)
{
  switch(p->kind)
  {
  case is_AProgram:
    return make_AProgram
      ( clone_LanguageDecl(p->u.aProgram_.languagedecl_)
      , clone_ListExtension(p->u.aProgram_.listextension_)
      , clone_ListDecl(p->u.aProgram_.listdecl_)
      );

  default:
    fprintf(stderr, "Error: bad kind field when cloning Program!\n");
    exit(1);
  }
}

ListStellaIdent clone_ListStellaIdent(ListStellaIdent liststellaident)
{
  if (liststellaident)
  {
    /* clone of non-empty list */
    return make_ListStellaIdent
      ( strdup(liststellaident->stellaident_)
      , clone_ListStellaIdent(liststellaident->liststellaident_)
      );
  }
  else return NULL; /* clone of empty list */
}

