Expr clone_Expr(Expr p)
{
  switch(p->kind)
  {
  case is_Sequence:
    return make_Sequence
      ( clone_Expr(p->u.sequence_.expr_1)
      , clone_Expr(p->u.sequence_.expr_2)
      );

  case is_Assign:
    return make_Assign
      ( clone_Expr(p->u.assign_.expr_1)
      , clone_Expr(p->u.assign_.expr_2)
      );

  case is_If:
    return make_If
      ( clone_Expr(p->u.if_.expr_1)
      , clone_Expr(p->u.if_.expr_2)
      , clone_Expr(p->u.if_.expr_3)
      );

  case is_Let:
    return make_Let
      ( clone_ListPatternBinding(p->u.let_.listpatternbinding_)
      , clone_Expr(p->u.let_.expr_)
      );

  case is_LetRec:
    return make_LetRec
      ( clone_ListPatternBinding(p->u.letRec_.listpatternbinding_)
      , clone_Expr(p->u.letRec_.expr_)
      );

  case is_TypeAbstraction:
    return make_TypeAbstraction
      ( clone_ListStellaIdent(p->u.typeAbstraction_.liststellaident_)
      , clone_Expr(p->u.typeAbstraction_.expr_)
      );

  case is_LessThan:
    return make_LessThan
      ( clone_Expr(p->u.lessThan_.expr_1)
      , clone_Expr(p->u.lessThan_.expr_2)
      );

  case is_LessThanOrEqual:
    return make_LessThanOrEqual
      ( clone_Expr(p->u.lessThanOrEqual_.expr_1)
      , clone_Expr(p->u.lessThanOrEqual_.expr_2)
      );

  case is_GreaterThan:
    return make_GreaterThan
      ( clone_Expr(p->u.greaterThan_.expr_1)
      , clone_Expr(p->u.greaterThan_.expr_2)
      );

  case is_GreaterThanOrEqual:
    return make_GreaterThanOrEqual
      ( clone_Expr(p->u.greaterThanOrEqual_.expr_1)
      , clone_Expr(p->u.greaterThanOrEqual_.expr_2)
      );

  case is_Equal:
    return make_Equal
      ( clone_Expr(p->u.equal_.expr_1)
      , clone_Expr(p->u.equal_.expr_2)
      );

  case is_NotEqual:
    return make_NotEqual
      ( clone_Expr(p->u.notEqual_.expr_1)
      , clone_Expr(p->u.notEqual_.expr_2)
      );

  case is_TypeAsc:
    return make_TypeAsc
      ( clone_Expr(p->u.typeAsc_.expr_)
      , clone_Type(p->u.typeAsc_.type_)
      );

  case is_TypeCast:
    return make_TypeCast
      ( clone_Expr(p->u.typeCast_.expr_)
      , clone_Type(p->u.typeCast_.type_)
      );

  case is_Abstraction:
    return make_Abstraction
      ( clone_ListParamDecl(p->u.abstraction_.listparamdecl_)
      , clone_Expr(p->u.abstraction_.expr_)
      );

  case is_ModBox:
    return make_ModBox
      ( clone_Modality(p->u.modBox_.modality_)
      , clone_Expr(p->u.modBox_.expr_)
      );

  case is_Variant:
    return make_Variant
      ( strdup(p->u.variant_.stellaident_)
      , clone_ExprData(p->u.variant_.exprdata_)
      );

  case is_Match:
    return make_Match
      ( clone_Expr(p->u.match_.expr_)
      , clone_ListMatchCase(p->u.match_.listmatchcase_)
      );

  case is_List:
    return make_List (clone_ListExpr(p->u.list_.listexpr_));

  case is_Add:
    return make_Add
      ( clone_Expr(p->u.add_.expr_1)
      , clone_Expr(p->u.add_.expr_2)
      );

  case is_Subtract:
    return make_Subtract
      ( clone_Expr(p->u.subtract_.expr_1)
      , clone_Expr(p->u.subtract_.expr_2)
      );

  case is_LogicOr:
    return make_LogicOr
      ( clone_Expr(p->u.logicOr_.expr_1)
      , clone_Expr(p->u.logicOr_.expr_2)
      );

  case is_Multiply:
    return make_Multiply
      ( clone_Expr(p->u.multiply_.expr_1)
      , clone_Expr(p->u.multiply_.expr_2)
      );

  case is_Divide:
    return make_Divide
      ( clone_Expr(p->u.divide_.expr_1)
      , clone_Expr(p->u.divide_.expr_2)
      );

  case is_LogicAnd:
    return make_LogicAnd
      ( clone_Expr(p->u.logicAnd_.expr_1)
      , clone_Expr(p->u.logicAnd_.expr_2)
      );

  case is_Ref:
    return make_Ref (clone_Expr(p->u.ref_.expr_));

  case is_Deref:
    return make_Deref (clone_Expr(p->u.deref_.expr_));

  case is_Application:
    return make_Application
      ( clone_Expr(p->u.application_.expr_)
      , clone_ListExpr(p->u.application_.listexpr_)
      );

  case is_TypeApplication:
    return make_TypeApplication
      ( clone_Expr(p->u.typeApplication_.expr_)
      , clone_ListType(p->u.typeApplication_.listtype_)
      );

  case is_DotRecord:
    return make_DotRecord
      ( clone_Expr(p->u.dotRecord_.expr_)
      , strdup(p->u.dotRecord_.stellaident_)
      );

  case is_DotTuple:
    return make_DotTuple
      ( clone_Expr(p->u.dotTuple_.expr_)
      , p->u.dotTuple_.integer_
      );

  case is_Tuple:
    return make_Tuple (clone_ListExpr(p->u.tuple_.listexpr_));

  case is_Record:
    return make_Record (clone_ListBinding(p->u.record_.listbinding_));

  case is_ConsList:
    return make_ConsList
      ( clone_Expr(p->u.consList_.expr_1)
      , clone_Expr(p->u.consList_.expr_2)
      );

  case is_Head:
    return make_Head (clone_Expr(p->u.head_.expr_));

  case is_IsEmpty:
    return make_IsEmpty (clone_Expr(p->u.isEmpty_.expr_));

  case is_Tail:
    return make_Tail (clone_Expr(p->u.tail_.expr_));

  case is_Panic:
    return make_Panic ();

  case is_Throw:
    return make_Throw (clone_Expr(p->u.throw_.expr_));

  case is_TryCatch:
    return make_TryCatch
      ( clone_Expr(p->u.tryCatch_.expr_1)
      , clone_Pattern(p->u.tryCatch_.pattern_)
      , clone_Expr(p->u.tryCatch_.expr_2)
      );

  case is_TryWith:
    return make_TryWith
      ( clone_Expr(p->u.tryWith_.expr_1)
      , clone_Expr(p->u.tryWith_.expr_2)
      );

  case is_TryCastAs:
    return make_TryCastAs
      ( clone_Expr(p->u.tryCastAs_.expr_1)
      , clone_Type(p->u.tryCastAs_.type_)
      , clone_Pattern(p->u.tryCastAs_.pattern_)
      , clone_Expr(p->u.tryCastAs_.expr_2)
      , clone_Expr(p->u.tryCastAs_.expr_3)
      );

  case is_Inl:
    return make_Inl (clone_Expr(p->u.inl_.expr_));

  case is_Inr:
    return make_Inr (clone_Expr(p->u.inr_.expr_));

  case is_Succ:
    return make_Succ (clone_Expr(p->u.succ_.expr_));

  case is_LogicNot:
    return make_LogicNot (clone_Expr(p->u.logicNot_.expr_));

  case is_Pred:
    return make_Pred (clone_Expr(p->u.pred_.expr_));

  case is_IsZero:
    return make_IsZero (clone_Expr(p->u.isZero_.expr_));

  case is_Handle:
    return make_Handle
      ( clone_Expr(p->u.handle_.expr_)
      , clone_ListHandler(p->u.handle_.listhandler_)
      );

  case is_Fix:
    return make_Fix (clone_Expr(p->u.fix_.expr_));

  case is_NatRec:
    return make_NatRec
      ( clone_Expr(p->u.natRec_.expr_1)
      , clone_Expr(p->u.natRec_.expr_2)
      , clone_Expr(p->u.natRec_.expr_3)
      );

  case is_Fold:
    return make_Fold
      ( clone_Type(p->u.fold_.type_)
      , clone_Expr(p->u.fold_.expr_)
      );

  case is_Unfold:
    return make_Unfold
      ( clone_Type(p->u.unfold_.type_)
      , clone_Expr(p->u.unfold_.expr_)
      );

  case is_ConstTrue:
    return make_ConstTrue ();

  case is_ConstFalse:
    return make_ConstFalse ();

  case is_ConstUnit:
    return make_ConstUnit ();

  case is_ConstInt:
    return make_ConstInt (p->u.constInt_.integer_);

  case is_ConstMemory:
    return make_ConstMemory (strdup(p->u.constMemory_.memoryaddress_));

  case is_Var:
    return make_Var (strdup(p->u.var_.stellaident_));

  default:
    fprintf(stderr, "Error: bad kind field when cloning Expr!\n");
    exit(1);
  }
}

