/********************   Recursive Destructors    **********************/

/* These free an entire abstract syntax tree
 * including all subtrees and strings.
 *
 * Will not work properly if there is sharing in the tree,
 * i.e., when some pointers are aliased.  In this case
 * it will attempt to free the same memory twice.
 */

void free_Program(Program p)
{
  switch(p->kind)
  {
  case is_AProgram:
    free_LanguageDecl(p->u.aProgram_.languagedecl_);
    free_ListExtension(p->u.aProgram_.listextension_);
    free_ListDecl(p->u.aProgram_.listdecl_);
    break;

  default:
    fprintf(stderr, "Error: bad kind field when freeing Program!\n");
    exit(1);
  }
  free(p);
}

void free_ListStellaIdent(ListStellaIdent liststellaident)
{
  if (liststellaident)
  {
    free(liststellaident->stellaident_);
    free_ListStellaIdent(liststellaident->liststellaident_);
    free(liststellaident);
  }
}

void free_LanguageDecl(LanguageDecl p)
{
  switch(p->kind)
  {
  case is_LanguageCore:
    break;

  default:
    fprintf(stderr, "Error: bad kind field when freeing LanguageDecl!\n");
    exit(1);
  }
  free(p);
}

void free_Extension(Extension p)
{
  switch(p->kind)
  {
  case is_AnExtension:
    free_ListExtensionName(p->u.anExtension_.listextensionname_);
    break;

  default:
    fprintf(stderr, "Error: bad kind field when freeing Extension!\n");
    exit(1);
  }
  free(p);
}

void free_ListExtensionName(ListExtensionName listextensionname)
{
  if (listextensionname)
  {
    free(listextensionname->extensionname_);
    free_ListExtensionName(listextensionname->listextensionname_);
    free(listextensionname);
  }
}

void free_ListExtension(ListExtension listextension)
{
  if (listextension)
  {
    free_Extension(listextension->extension_);
    free_ListExtension(listextension->listextension_);
    free(listextension);
  }
}

void free_Decl(Decl p)
{
  switch(p->kind)
  {
  case is_DeclFun:
    free_ListAnnotation(p->u.declFun_.listannotation_);
    free(p->u.declFun_.stellaident_);
    free_ListParamDecl(p->u.declFun_.listparamdecl_);
    free_ReturnType(p->u.declFun_.returntype_);
    free_ThrowType(p->u.declFun_.throwtype_);
    free_ListDecl(p->u.declFun_.listdecl_);
    free_Expr(p->u.declFun_.expr_);
    break;

  case is_DeclFunGeneric:
    free_ListAnnotation(p->u.declFunGeneric_.listannotation_);
    free(p->u.declFunGeneric_.stellaident_);
    free_ListStellaIdent(p->u.declFunGeneric_.liststellaident_);
    free_ListParamDecl(p->u.declFunGeneric_.listparamdecl_);
    free_ReturnType(p->u.declFunGeneric_.returntype_);
    free_ThrowType(p->u.declFunGeneric_.throwtype_);
    free_ListDecl(p->u.declFunGeneric_.listdecl_);
    free_Expr(p->u.declFunGeneric_.expr_);
    break;

  case is_DeclFunMod:
    free_ListAnnotation(p->u.declFunMod_.listannotation_);
    free_Modality(p->u.declFunMod_.modality_);
    free(p->u.declFunMod_.stellaident_);
    free_ListParamDecl(p->u.declFunMod_.listparamdecl_);
    free_ReturnType(p->u.declFunMod_.returntype_);
    free_ThrowType(p->u.declFunMod_.throwtype_);
    free_ListDecl(p->u.declFunMod_.listdecl_);
    free_Expr(p->u.declFunMod_.expr_);
    break;

  case is_DeclTypeAlias:
    free(p->u.declTypeAlias_.stellaident_);
    free_Type(p->u.declTypeAlias_.type_);
    break;

  case is_DeclExceptionType:
    free_Type(p->u.declExceptionType_.type_);
    break;

  case is_DeclExceptionVariant:
    free(p->u.declExceptionVariant_.stellaident_);
    free_Type(p->u.declExceptionVariant_.type_);
    break;

  default:
    fprintf(stderr, "Error: bad kind field when freeing Decl!\n");
    exit(1);
  }
  free(p);
}

void free_ListDecl(ListDecl listdecl)
{
  if (listdecl)
  {
    free_Decl(listdecl->decl_);
    free_ListDecl(listdecl->listdecl_);
    free(listdecl);
  }
}

