void free_OptionalTyping(OptionalTyping p)
{
  switch(p->kind)
  {
  case is_NoTyping:
    break;

  case is_SomeTyping:
    free_Type(p->u.someTyping_.type_);
    break;

  default:
    fprintf(stderr, "Error: bad kind field when freeing OptionalTyping!\n");
    exit(1);
  }
  free(p);
}

