void free_Pattern(Pattern p)
{
  switch(p->kind)
  {
  case is_PatternCastAs:
    free_Pattern(p->u.patternCastAs_.pattern_);
    free_Type(p->u.patternCastAs_.type_);
    break;

  case is_PatternAsc:
    free_Pattern(p->u.patternAsc_.pattern_);
    free_Type(p->u.patternAsc_.type_);
    break;

  case is_PatternVariant:
    free(p->u.patternVariant_.stellaident_);
    free_PatternData(p->u.patternVariant_.patterndata_);
    break;

  case is_PatternInl:
    free_Pattern(p->u.patternInl_.pattern_);
    break;

  case is_PatternInr:
    free_Pattern(p->u.patternInr_.pattern_);
    break;

  case is_PatternTuple:
    free_ListPattern(p->u.patternTuple_.listpattern_);
    break;

  case is_PatternRecord:
    free_ListLabelledPattern(p->u.patternRecord_.listlabelledpattern_);
    break;

  case is_PatternList:
    free_ListPattern(p->u.patternList_.listpattern_);
    break;

  case is_PatternCons:
    free_Pattern(p->u.patternCons_.pattern_1);
    free_Pattern(p->u.patternCons_.pattern_2);
    break;

  case is_PatternFalse:
    break;

  case is_PatternTrue:
    break;

  case is_PatternUnit:
    break;

  case is_PatternInt:
    break;

  case is_PatternSucc:
    free_Pattern(p->u.patternSucc_.pattern_);
    break;

  case is_PatternVar:
    free(p->u.patternVar_.stellaident_);
    break;

  default:
    fprintf(stderr, "Error: bad kind field when freeing Pattern!\n");
    exit(1);
  }
  free(p);
}

